SELECT * FROM sys_sync_task
WHERE tenant_id = #{tenantId}
  AND message_key = #{messageKey}
  AND delete_flag = 0

SELECT * FROM sys_sync_task
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND delete_flag = 0

SELECT * FROM sys_sync_task
WHERE tenant_id = #{tenantId}
  AND sync_action = #{syncAction}
  AND business_key_hash = #{businessKeyHash}
  AND status = 'PENDING'
  AND delete_flag = 0
LIMIT 1

mapper.update:
UPDATE sys_sync_task
   SET status = 'SUCCESS',
       locked_at = NULL,
       locked_by = NULL,
       last_error = NULL,
       updated_at = #{now}
 WHERE id = #{id}
   AND locked_by = #{workerId}
   AND delete_flag = 0

UPDATE sys_sync_task
   SET status = 'FAILED',
       locked_at = NULL,
       locked_by = NULL,
       last_error = #{lastError},
       updated_at = #{now}
 WHERE id = #{id}
   AND locked_by = #{workerId}
   AND delete_flag = 0

mapper.sql:
WHERE delete_flag = 0
  AND tenant_id = #{params.tenantId}

    AND sync_action = #{params.syncAction}


    AND status = #{params.status}


    AND phase = #{params.phase}


    AND batch_key = #{params.batchKey}


    AND business_key = #{params.businessKey}

mapper.select:
SELECT * FROM sys_sync_task

ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT * FROM sys_sync_task
 WHERE tenant_id = #{tenantId}
   AND batch_key_hash = #{batchKeyHash}
   AND delete_flag = 0
 ORDER BY created_at ASC
